export function projectNoeliaAnnulmentSource(file,value){
 assert.equal(typeof file,'string','NOELIA_ANNULMENT_SOURCE_PATH_REQUIRED');
 value=projectNoeliaLiquidationReviewSource(file,value);
 if(!Object.hasOwn(annulmentSourcePins,file))return value;
 assert.equal(typeof value,'string','NOELIA_ANNULMENT_SOURCE_TEXT_REQUIRED');
 const pin=annulmentSourcePins[file];assert.equal(Buffer.byteLength(value),pin.afterBytes,'NOELIA_ANNULMENT_CURRENT_BYTES_CHANGED:'+file);assert.equal(hash(value),pin.afterSha256,'NOELIA_ANNULMENT_CURRENT_SOURCE_CHANGED:'+file);
 let source=Buffer.from(value,'utf8');
 for(const op of [...pin.inverse].reverse()){
  const after=Buffer.from(op.afterBase64,'base64'),before=Buffer.from(op.beforeBase64,'base64');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'NOELIA_ANNULMENT_INVERSE_SPAN_CHANGED:'+file);
  source=Buffer.concat([source.subarray(0,op.afterOffset),before,source.subarray(op.afterOffset+after.length)]);
 }
 assert.equal(source.length,pin.beforeBytes,'NOELIA_ANNULMENT_PARENT_BYTES_CHANGED:'+file);assert.equal(hash(source),pin.beforeSha256,'NOELIA_ANNULMENT_PARENT_SOURCE_CHANGED:'+file);return source.toString('utf8');
}

